package com.example.media

import android.content.Context
import android.media.AudioAttributes
import android.media.MediaPlayer
import androidx.annotation.RawRes
import com.example.R

/**
 * Night-time soundscapes for the sleep timer (v3.6.0).
 *
 * Each entry maps to a loopable WAV in `res/raw`, generated by
 * `tools/make_ambience.py` and mixed **under** the music at [AmbiencePlayer]'s
 * own volume, so the user can fall asleep to rain while a quiet playlist still
 * plays. Nothing is streamed: the files ship with the app, which is why they
 * work offline and start instantly.
 */
enum class Ambience(
    val label: String,
    val blurb: String,
    @RawRes val resId: Int
) {
    RAIN("Hujan", "Hujan stabil — paling mudah membawa tidur", R.raw.amb_rain),
    FIRE("Api Unggun", "Riak api dan kayu yang sesekali pecah", R.raw.amb_fire),
    WAVES("Ombak", "Ombak pelan yang naik dan turun", R.raw.amb_waves),
    NIGHT("Malam", "Jangkrik dan angin malam", R.raw.amb_night)
}

/**
 * Plays one [Ambience] loop on top of the music.
 *
 * Deliberately does **not** request audio focus: the whole point is to mix with
 * the track that is already playing. Volume is controlled separately, and the
 * player is a single reused [MediaPlayer] so switching ambience never leaves a
 * second loop running behind the first.
 */
class AmbiencePlayer(private val context: Context) {

    private var player: MediaPlayer? = null
    private var current: Ambience? = null

    /** Which loop is audible right now, or null when silence is selected. */
    val playing: Ambience? get() = current

    fun play(ambience: Ambience, volume: Float) {
        if (current == ambience && player?.isPlaying == true) {
            setVolume(volume)
            return
        }
        stop()
        val created = MediaPlayer.create(context, ambience.resId) ?: return
        created.isLooping = true
        created.setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_MEDIA)
                .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                .build()
        )
        created.setVolume(volume, volume)
        runCatching { created.start() }
            .onFailure {
                created.release()
                return
            }
        player = created
        current = ambience
    }

    fun setVolume(volume: Float) {
        val clamped = volume.coerceIn(0f, 1f)
        player?.setVolume(clamped, clamped)
    }

    fun stop() {
        player?.let { mp ->
            runCatching { if (mp.isPlaying) mp.pause() }
            runCatching { mp.stop() }
            runCatching { mp.release() }
        }
        player = null
        current = null
    }

    fun release() = stop()
}
